CREATE VIEW dbo.IV_Q$VENDA_LOCACAO ( SeqPessoa, Pessoa, SeqQuestionario, SeqFormulario, Formulario,  DtaRealizacao, UsuInclusao, DtaAlteracao, UsuAlteracao,  Observacao,  SeqHistorico, Resultado, Processo, Departamento, LinkDocto, LinkNro, LinkSerie , TIPO_EQUIP_MANITOU, MARCA_M, MODELO_EQUIPM, N_PEDIDO_VDM, TIPO_TORRE, TIPO_RODADO, BITOLA, ACESSORIOS, IMPLEMENTOS, EASY_MANAGER, OUTRAS_CONFIG, AGREGA_DESAGREG, VALOR_TOTA, VALOR_SINAL, DATA_SINAL, VALOR_FINANC, TIPO_PGTO, DATA_PGTO, DATA_ATUALIZADA, COD_FINAME, TX_FLAT, TAXA_FLT_, INST_FINANC, N_AGENCIA, NOME_AGENC, NOME_GER_AGENC, TEL_AGENC, CONTATO_AGENCIA, INF_FINANC, CHASSI_EQUIP, APROV_CRED, N__DO_PAC, PAC_EMITIDO, N_CONTRATO, PREVISAO_DE_FATURAME, DATA_PED_VD, DATA_PROC_BC, N__NF, DATA_FAT, NF_REFAT, OBS)     AS SELECT TBASE.SEQPESSOA, TBASE.NOMERAZAO, QST.SEQQUESTIONARIO, FRM.SEQFORMULARIO, FRM.DESCRICAO,  QST.DTAREALIZACAO, QST.USUINCLUSAO, QST.DTAALTERACAO, QST.USUALTERACAO, QST.OBS,  QST.SEQHISTORICO, QST.RESULTADO, QST.PROCESSO, QST.DEPARTAMENTO,  QST.LINKDOCTO, QST.LINKNRO, QST.LINKSERIE , TABF.TIPO_EQUIP_MANITOU, TABF.MARCA_M, TABF.MODELO_EQUIPM, TABF.N_PEDIDO_VDM, TABF.TIPO_TORRE, TABF.TIPO_RODADO, TABF.BITOLA, TABF.ACESSORIOS, TABF.IMPLEMENTOS, TABF.EASY_MANAGER, TABF.OUTRAS_CONFIG, TABF.AGREGA_DESAGREG, TABF.VALOR_TOTA, TABF.VALOR_SINAL, TABF.DATA_SINAL, TABF.VALOR_FINANC, TABF.TIPO_PGTO, TABF.DATA_PGTO, TABF.DATA_ATUALIZADA, TABF.COD_FINAME, TABF.TX_FLAT, TABF.TAXA_FLT_, TABF.INST_FINANC, TABF.N_AGENCIA, TABF.NOME_AGENC, TABF.NOME_GER_AGENC, TABF.TEL_AGENC, TABF.CONTATO_AGENCIA, TABF.INF_FINANC, TABF.CHASSI_EQUIP, TABF.APROV_CRED, TABF.N__DO_PAC, TABF.PAC_EMITIDO, TABF.N_CONTRATO, TABF.PREVISAO_DE_FATURAME, TABF.DATA_PED_VD, TABF.DATA_PROC_BC, TABF.N__NF, TABF.DATA_FAT, TABF.NF_REFAT, TABF.OBS    FROM IV_Q_VENDA_LOCACAO TABF  	JOIN IV_QUESTIONARIO QST ON QST.SEQQUESTIONARIO =  TABF.SEQQUESTIONARIO  	JOIN IV_FORMULARIO FRM ON   FRM.SEQFORMULARIO = QST.SEQFORMULARIO  	JOIN GE_PESSOA TBASE ON TBASE.SEQPESSOA = QST.SEQPESSOA 